 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    border = next((v for row in grid for v in row if v not in (5, 8)), None)
    # The uniform non-line color is the background; the other color is the outline.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    outline = next(v for v in colors if v != bg)
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] != outline and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] != outline and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != outline and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != outline and (r,c) not in seen:
                out[r][c] = 4
    return out
